function validate([l, r]) {
  if (!Number.isInteger(l) || !Number.isInteger(r)) return 'l and r are whole numbers.';
  if (l < 1 || r > 1000000000) return 'l and r are between 1 and 10^9.';
  if (l > r) return 'l must not be greater than r.';
  return null;
}

