function nonSpecialCount(l, r) {
  // Count each number's proper divisors by trial division, stopping as soon as there are more than two.
  let count = 0;
  for (let x = l; x <= r; x++) {
    let proper = 0;
    for (let d = 1; d * d <= x && proper <= 2; d++) {
      if (x % d !== 0) continue;
      const other = x / d;
      if (d !== x) proper++;
      if (other !== d && other !== x) proper++;
    }
    if (proper !== 2) count++;
  }
  return count;
}

