function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    // The whole allowed range, or a wide range ending near 10^9.
    if (rand() < 0.4) return [1, 1000000000];
    const r = pick(900000000, 1000000000);
    return [pick(1, r), r];
  }
  if (rand() < 0.35) {
    // A short window around the square of a prime, sometimes a large one.
    const primes = [2, 3, 5, 7, 11, 13, 101, 997, 9973, 31607];
    const square = primes[Math.floor(rand() * primes.length)] ** 2;
    return [Math.max(1, square - pick(0, 20)), square + pick(0, 20)];
  }
  const r = pick(1, 300);
  return [pick(1, r), r];
}
